// Deployment settings from /config.json (generated by nginx from environment variables).
// Everything about what the dashboard shows lives in IoT Open (metadata + layout file).

// The directory the app is served from, e.g. "/" or "/dashboard/". Every URL the app uses (API, MQTT,
// config, images) is relative to it, so the container also works under a path prefix behind a reverse proxy.
export const BASE_URL = new URL('./', window.location.href.split('#')[0]).pathname;
export const appUrl = (path) => BASE_URL + String(path).replace(/^\//, '');

export const config = {
  appTitle: 'Dashboard',
  liveUpdates: true,
  // map tiles for the Tracker widget ({z}/{x}/{y} template); '' = no map background, only the tracks
  mapTiles: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
  mapAttribution: '© OpenStreetMap-bidragsgivare',
};

export async function loadConfig() {
  try {
    const res = await fetch(appUrl('config.json'), { cache: 'no-store' });
    if (res.ok) {
      const c = await res.json();
      for (const [k, v] of Object.entries(c)) if (v !== '' && v !== undefined && v !== null) config[k] = v;
      // an empty MAP_TILES turns the map background off (the CSP then allows no tile server either)
      if (c.mapTiles === '') config.mapTiles = '';
    }
  } catch {
    /* keep defaults */
  }
  config.liveUpdates = !(config.liveUpdates === false || config.liveUpdates === 'false');
  document.title = config.appTitle;
  return config;
}
